mapper.select:
        select  t.person_name,t.person_name personName,t.res_param,t.res_param resParam,t.machine_id,t.machine_id machineId,t.create_time,t.create_time createTime,t.log_id,t.log_id logId,t.person_id,t.person_id personId,t.req_param,t.req_param reqParam,t.state,t.community_id,t.community_id communityId,t.log_action,t.log_action logAction 
from meter_machine_log t 
where 1 =1 

   and t.person_name= #{personName}


   and t.res_param= #{resParam}


   and t.machine_id= #{machineId}


   and t.create_time= #{createTime}


   and t.log_id= #{logId}


   and t.person_id= #{personId}


   and t.req_param= #{reqParam}


   and t.state= #{state}


   and t.community_id= #{communityId}


   and t.log_action= #{logAction}

order by t.create_time desc

   limit #{page}, #{row}

